apply.script:
$p='HKCU:\Software\Microsoft\DirectX\UserGpuPreferences'; $n='DirectXUserGlobalSettings'; $k='SwapEffectUpgradeEnable'; $v='1'
if (-not (Test-Path -LiteralPath $p)) { New-Item -Path $p | Out-Null }
$cur = (Get-ItemProperty -LiteralPath $p -Name $n -ErrorAction SilentlyContinue).$n
$pairs = New-Object System.Collections.Specialized.OrderedDictionary
if ($cur) { foreach ($t in $cur.Split(';')) { if ($t -match '^\s*([^=]+?)\s*=\s*(.*?)\s*$') { $pairs[$matches[1]] = $matches[2] } } }
$pairs[$k] = $v
$s = ''; foreach ($e in $pairs.GetEnumerator()) { $s += ($e.Key + '=' + $e.Value + ';') }
New-ItemProperty -LiteralPath $p -Name $n -PropertyType String -Value $s -Force | Out-Null

