apply.script:
$sig = @'
using System; using System.Runtime.InteropServices;
public static class HzSpi {
  [StructLayout(LayoutKind.Sequential)] public struct ANIMATIONINFO { public uint cbSize; public int iMinAnimate; }
  [DllImport("user32.dll", SetLastError=true)] public static extern bool SystemParametersInfo(uint a, uint u, IntPtr p, uint f);
  [DllImport("user32.dll", SetLastError=true)] public static extern bool SystemParametersInfo(uint a, uint u, ref ANIMATIONINFO p, uint f);
  public static void SetBoolPv(uint a, bool on) { SystemParametersInfo(a, 0, on ? new IntPtr(1) : IntPtr.Zero, 3); }
  public static void SetBoolUi(uint a, bool on) { SystemParametersInfo(a, on ? 1u : 0u, IntPtr.Zero, 3); }
  public static void SetMinMax(bool on) { var ai = new ANIMATIONINFO(); ai.cbSize = 8; ai.iMinAnimate = on ? 1 : 0; SystemParametersInfo(0x49, 8, ref ai, 3); }
}
'@
if (-not ('HzSpi' -as [type])) { Add-Type -TypeDefinition $sig }
[HzSpi]::SetMinMax($false)                 # AnimateMinMax (SPI_SETANIMATION 0x49)
[HzSpi]::SetBoolPv(0x1043, $false)          # ControlAnimations (SPI_SETCLIENTAREAANIMATION)
[HzSpi]::SetBoolPv(0x1005, $false)          # ComboBoxAnimation
[HzSpi]::SetBoolPv(0x1007, $false)          # ListBoxSmoothScrolling
[HzSpi]::SetBoolPv(0x1003, $false)          # MenuAnimation
[HzSpi]::SetBoolPv(0x1015, $false)          # SelectionFade
[HzSpi]::SetBoolPv(0x1017, $false)          # TooltipAnimation
[HzSpi]::SetBoolPv(0x101B, $false)          # CursorShadow
[HzSpi]::SetBoolPv(0x1025, $false)          # DropShadow
$adv='HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
New-ItemProperty -LiteralPath $adv -Name TaskbarAnimations -PropertyType DWord -Value 0 -Force | Out-Null
New-ItemProperty -LiteralPath $adv -Name ListviewAlphaSelect -PropertyType DWord -Value 0 -Force | Out-Null
New-ItemProperty -LiteralPath $adv -Name ListviewShadow -PropertyType DWord -Value 0 -Force | Out-Null
New-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\DWM' -Name EnableAeroPeek -PropertyType DWord -Value 0 -Force | Out-Null
$vfx='HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects'
if (-not (Test-Path -LiteralPath $vfx)) { New-Item -Path $vfx | Out-Null }
New-ItemProperty -LiteralPath $vfx -Name VisualFXSetting -PropertyType DWord -Value 3 -Force | Out-Null

