'@
if (-not ('HzSpi' -as [type])) { Add-Type -TypeDefinition $sig }
function Get-Def([string]$name, [int]$fallback) { $k = 'HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects\' + $name; $d = (Get-ItemProperty -LiteralPath $k -Name DefaultValue -ErrorAction SilentlyContinue).DefaultValue; if ($d -eq $null) { return $fallback } else { return [int]$d } }
[HzSpi]::SetMinMax((Get-Def 'AnimateMinMax' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1043, (Get-Def 'ControlAnimations' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1005, (Get-Def 'ComboBoxAnimation' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1007, (Get-Def 'ListBoxSmoothScrolling' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1003, (Get-Def 'MenuAnimation' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1015, (Get-Def 'SelectionFade' 1) -ne 0)
[HzSpi]::SetBoolPv(0x1017, (Get-Def 'TooltipAnimation' 1) -ne 0)
[HzSpi]::SetBoolPv(0x101B, (Get-Def 'CursorShadow' 0) -ne 0)
[HzSpi]::SetBoolPv(0x1025, (Get-Def 'DropShadow' 1) -ne 0)
$adv='HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\Advanced'
New-ItemProperty -LiteralPath $adv -Name TaskbarAnimations -PropertyType DWord -Value (Get-Def 'TaskbarAnimations' 1) -Force | Out-Null
New-ItemProperty -LiteralPath $adv -Name ListviewAlphaSelect -PropertyType DWord -Value (Get-Def 'ListviewAlphaSelect' 1) -Force | Out-Null
New-ItemProperty -LiteralPath $adv -Name ListviewShadow -PropertyType DWord -Value (Get-Def 'ListviewShadow' 1) -Force | Out-Null
New-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\DWM' -Name EnableAeroPeek -PropertyType DWord -Value (Get-Def 'DWMAeroPeekEnabled' 1) -Force | Out-Null
Remove-ItemProperty -LiteralPath 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects' -Name VisualFXSetting -ErrorAction SilentlyContinue
